          <button type="button" class="bp-btn" data-move="1" data-native data-test="bowl-move-r" aria-label="move right"><svg viewBox="0 0 64 64" aria-hidden="true"><path class="f" d="M52 32 L20 10 L20 54 Z"/></svg></button>
